-- 201: Original BrillaPrep WASSCE BrillaPrep transitional Basketry beta content blueprint questions, part 9.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_201_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_201_guard;
INSERT INTO _migration_201_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_033' AND NOT (q.topic_id IS 'topic_was_basketry_b004_7' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the soundest basis for setting a sustainable selling price?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Copy the lowest competing price even when construction and quality differ","B. Ignore rejected trials and normal waste when estimating production cost","C. Total cost plus a reasoned profit margin, checked against value and market conditions","D. Recover direct material only and treat skilled labour as having no cost"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Pricing should recover materials, labour and allocated overhead before profit, while comparison with customer value and market conditions tests whether the offer is commercially realistic. Therefore the correct answer is C: Total cost plus a reasoned profit margin, checked against value and market conditions.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_033' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_201_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_034' AND NOT (q.topic_id IS 'topic_was_basketry_b004_7' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is the sequence of operations written before producing several matching baskets?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It coordinates preparation, weaving and finishing while reducing delay and rework","B. Inspect the completed batch after packaging rather than at intermediate stages","C. Apply the final finish before checking dimensions or structural joints","D. Prepare materials separately for each unit without a common specification"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A planned route groups suitable operations, identifies dependencies and quality checks, and makes time and material needs visible before repeated errors affect the full production run. Therefore the correct answer is A: It coordinates preparation, weaving and finishing while reducing delay and rework.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_034' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_201_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_035' AND NOT (q.topic_id IS 'topic_was_basketry_b004_7' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which portfolio entry best demonstrates development of an original basket design?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Annotated sketches, material trials, process photographs and evaluation of the result","B. A downloaded basket image presented without identifying it as reference","C. One final photograph without dimensions, trials or reflection","D. A list of available tools that never connects them to design decisions"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A strong portfolio links intention to testing and outcome, showing how observations from samples and construction informed changes rather than displaying only an unexplained final object. Therefore the correct answer is A: Annotated sketches, material trials, process photographs and evaluation of the result.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_035' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_201_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_036' AND NOT (q.topic_id IS 'topic_was_basketry_b004_8' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which inspection finding gives the strongest evidence of sound basketry workmanship?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A flexible rim that changes shape whenever the basket is lifted","B. Attractive colour that conceals irregular gaps and loose courses","C. Uneven tension accepted because all handmade work must be structurally irregular","D. Even tension, stable form, secure borders and no hazardous projecting ends"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Quality includes structure, fitness and safety as well as appearance, so regular tension, accurate form and securely finished ends provide evidence that the product can perform its intended service. Therefore the correct answer is D: Even tension, stable form, secure borders and no hazardous projecting ends.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_036' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_033', 'topic_was_basketry_b004_7', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'What is the soundest basis for setting a sustainable selling price?', 'multiple_choice', NULL, '["A. Copy the lowest competing price even when construction and quality differ","B. Ignore rejected trials and normal waste when estimating production cost","C. Total cost plus a reasoned profit margin, checked against value and market conditions","D. Recover direct material only and treat skilled labour as having no cost"]', 'C', 'Pricing should recover materials, labour and allocated overhead before profit, while comparison with customer value and market conditions tests whether the offer is commercially realistic. Therefore the correct answer is C: Total cost plus a reasoned profit margin, checked against value and market conditions.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_7', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_034', 'topic_was_basketry_b004_7', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Why is the sequence of operations written before producing several matching baskets?', 'multiple_choice', NULL, '["A. It coordinates preparation, weaving and finishing while reducing delay and rework","B. Inspect the completed batch after packaging rather than at intermediate stages","C. Apply the final finish before checking dimensions or structural joints","D. Prepare materials separately for each unit without a common specification"]', 'A', 'A planned route groups suitable operations, identifies dependencies and quality checks, and makes time and material needs visible before repeated errors affect the full production run. Therefore the correct answer is A: It coordinates preparation, weaving and finishing while reducing delay and rework.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_7', 'Explain', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_035', 'topic_was_basketry_b004_7', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Which portfolio entry best demonstrates development of an original basket design?', 'multiple_choice', NULL, '["A. Annotated sketches, material trials, process photographs and evaluation of the result","B. A downloaded basket image presented without identifying it as reference","C. One final photograph without dimensions, trials or reflection","D. A list of available tools that never connects them to design decisions"]', 'A', 'A strong portfolio links intention to testing and outcome, showing how observations from samples and construction informed changes rather than displaying only an unexplained final object. Therefore the correct answer is A: Annotated sketches, material trials, process photographs and evaluation of the result.', 'medium', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_7', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_036', 'topic_was_basketry_b004_8', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Which inspection finding gives the strongest evidence of sound basketry workmanship?', 'multiple_choice', NULL, '["A. A flexible rim that changes shape whenever the basket is lifted","B. Attractive colour that conceals irregular gaps and loose courses","C. Uneven tension accepted because all handmade work must be structurally irregular","D. Even tension, stable form, secure borders and no hazardous projecting ends"]', 'D', 'Quality includes structure, fitness and safety as well as appearance, so regular tension, accurate form and securely finished ends provide evidence that the product can perform its intended service. Therefore the correct answer is D: Even tension, stable form, secure borders and no hazardous projecting ends.', 'hard', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_8', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_basketry_b004_033', 'q_was_basketry_b004_034', 'q_was_basketry_b004_035', 'q_was_basketry_b004_036');
DELETE FROM _migration_201_guard;
INSERT INTO _migration_201_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions WHERE id IN ('q_was_basketry_b004_033', 'q_was_basketry_b004_034', 'q_was_basketry_b004_035', 'q_was_basketry_b004_036')) = 4 AND (SELECT COUNT(*) FROM question_content_releases r WHERE r.question_id IN ('q_was_basketry_b004_033', 'q_was_basketry_b004_034', 'q_was_basketry_b004_035', 'q_was_basketry_b004_036') AND r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 4 THEN 1 ELSE 0 END;
